// Check if boxes are completely separated
bool separated = true;
for (dim_t i = 0; i < 3; ++i) {
    if (box1.Max(i) < box2.Min(i) || box2.Max(i) < box1.Min(i)) {
        continue;  // Still could be adjacent
    }
    separated = false;
    break;
}
if (separated) {
    return BoxRelation::Separated;
}

// Check if boxes are overlapping
bool overlapped = false;
for (dim_t i = 0; i < 3; ++i) {
    if (box1.Max(i) >= box2.Min(i) && box2.Max(i) >= box1.Min(i)) {
        overlapped = true;
        break;
    }
}
if (overlapped) {
    return BoxRelation::Overlapped;
}

// If not separated and not overlapped, they must be adjacent
return BoxRelation::Adjacent;

